{
  "world_id": "wld_sparrow",
  "title": "The Bay at the End of the World",
  "logline": "As the dome's irreplaceable battery fails, engineer Elara must abandon her attempt to save it and decide whether to spend its last power on research or on keeping the only habitable bay alive long enough for rescue.",
  "theme": "Survival sometimes means letting go of what cannot be saved.",
  "acts": [
    {
      "id": "act_setup",
      "title": "The Failing Rhythm",
      "purpose": "setup",
      "scenes": [
        {
          "id": "scn_battery_warning",
          "title": "A Note Out of Time",
          "summary": "Elara hears an irregular pulse in the power grid and checks the telemetry: the single life-support battery is draining faster than expected. She begins a methodical diagnosis, still convinced the fault can be repaired.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Identify why the battery is losing power and find a repair before the bay becomes uninhabitable.",
          "conflict": "The readings worsen, and the battery cannot be replaced once depleted.",
          "outcome": "The loss is confirmed, but Elara commits to repairing the battery rather than preparing to ration its remaining charge."
        },
        {
          "id": "scn_first_repair",
          "title": "The Repair That Holds",
          "summary": "Elara tests the accessible connections and monitors their hum, searching for a fault she can correct. The readings briefly steady, then resume their decline.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Restore stable battery output and protect the bay's pressure and heat.",
          "conflict": "Her tests reveal no faulty connection; the apparent improvement is temporary, and each test consumes more of the dwindling reserve.",
          "outcome": "Elara has no repair to make, but her stubbornness keeps her focused on another test instead of conserving power.",
          "depends_on": [
            "scn_battery_warning"
          ]
        }
      ]
    },
    {
      "id": "act_rising_action",
      "title": "The Cost of Hope",
      "purpose": "rising_action",
      "scenes": [
        {
          "id": "scn_load_audit",
          "title": "Every Draw",
          "summary": "Elara audits the bay's active systems, listening to each change as she traces its draw. The research instruments are using power that could otherwise remain available to life support.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Find enough usable power to keep the bay habitable until rescue.",
          "conflict": "Reducing nonessential loads means giving up the research work she came to preserve, while her hope of repairing the battery remains.",
          "outcome": "Elara identifies the research instruments as a load she can sacrifice, but delays shutting them down to attempt one last diagnosis.",
          "depends_on": [
            "scn_first_repair"
          ]
        },
        {
          "id": "scn_last_diagnosis",
          "title": "No Loose Connection",
          "summary": "Elara listens to the grid through another diagnostic cycle and compares the changing pulse with the telemetry. The battery's decline is internal, not a fault she can reach or repair.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Prove that a repair remains possible before committing to rationing.",
          "conflict": "The evidence is conclusive, but accepting it means confronting the certainty of entropy and surrendering the goal that has kept her moving.",
          "outcome": "Elara confirms the battery cannot be saved; the extra diagnosis has narrowed the time left to choose what the remaining power will support.",
          "depends_on": [
            "scn_load_audit"
          ]
        },
        {
          "id": "scn_remaining_charge",
          "title": "A Shorter Horizon",
          "summary": "With the battery still falling, Elara calculates what remains for the bay's essential systems. She can no longer treat every active system as equally worth saving.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Choose a power plan that gives the bay the best chance of lasting until rescue.",
          "conflict": "Keeping the research instruments running preserves her work but shortens the time available for pressure and heat; rescue may not arrive in time either way.",
          "outcome": "Elara decides the bay and the life within it matter more than the research, though switching off the instruments will make that loss irreversible.",
          "depends_on": [
            "scn_last_diagnosis"
          ]
        }
      ]
    },
    {
      "id": "act_climax",
      "title": "What Remains",
      "purpose": "climax",
      "scenes": [
        {
          "id": "scn_cut_research_load",
          "title": "The Last Switch",
          "summary": "Elara shuts down the research instruments and directs the remaining battery power toward life support. The bay's systems settle into a reduced, fragile rhythm; the research is lost, and the battery continues to drain.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Preserve pressure and heat in the only habitable bay for as long as the battery allows.",
          "conflict": "She must let go of both the research and her belief that persistence can defeat the battery's irreversible failure.",
          "outcome": "Life support remains powered, but no repair has been made and the bay has only the battery's remaining charge.",
          "depends_on": [
            "scn_remaining_charge"
          ]
        }
      ]
    },
    {
      "id": "act_resolution",
      "title": "The Remaining Hours",
      "purpose": "resolution",
      "scenes": [
        {
          "id": "scn_failure_record",
          "title": "An Honest Record",
          "summary": "Elara records the battery's condition and the choice she made, without claiming that rescue is certain or that the bay can last indefinitely. She stops searching for a repair that does not exist.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Leave an accurate account while conserving the bay's remaining power.",
          "conflict": "Her old instinct is to keep troubleshooting, but every unnecessary effort spends time and attention she can no longer recover.",
          "outcome": "Elara accepts the limits of the battery and keeps her effort focused on the surviving life-support systems.",
          "depends_on": [
            "scn_cut_research_load"
          ]
        },
        {
          "id": "scn_waiting_bay",
          "title": "The Only Warmth",
          "summary": "Alone in the dimming bay, Elara listens to the life-support rhythm she chose to preserve. The research is gone and the battery still dwindles, but for now the bay remains habitable.",
          "location_id": "loc_bay",
          "character_ids": [
            "chr_elara"
          ],
          "goal": "Endure in the bay while keeping its remaining life support intact for a possible rescue.",
          "conflict": "The battery cannot be repaired or replenished, and the empty moon offers no guarantee that anyone will arrive in time.",
          "outcome": "Elara faces an uncertain wait without false hope, having chosen to save the bay's remaining warmth and pressure rather than what could not be saved.",
          "depends_on": [
            "scn_failure_record"
          ]
        }
      ]
    }
  ]
}

